const message = $input.first().json;
const content = message.content.toLowerCase();

// Banned words list
const bannedWords = ['spam', 'scam', 'hack', 'cheat', 'exploit', 'phishing'];
const hasBannedWord = bannedWords.some(word => content.includes(word));

// Spam patterns
const hasExcessiveCaps = (message.content.match(/[A-Z]/g) || []).length > message.content.length * 0.7 && message.content.length > 10;
const hasExcessiveEmoji = (content.match(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}]/gu) || []).length > 10;
const hasRepeatedChars = /(.)(\1{5,})/.test(content);
const hasExcessiveMentions = (content.match(/<@/g) || []).length > 5;
const hasExcessiveLinks = (content.match(/https?:\/\//g) || []).length > 3;

const isViolation = hasBannedWord || hasExcessiveCaps || hasExcessiveEmoji || hasRepeatedChars || hasExcessiveMentions || hasExcessiveLinks;

const reasons = [];
if (hasBannedWord) reasons.push('Banned word detected');
if (hasExcessiveCaps) reasons.push('Excessive caps');
if (hasExcessiveEmoji) reasons.push('Emoji spam');
if (hasRepeatedChars) reasons.push('Character spam');
if (hasExcessiveMentions) reasons.push('Mention spam');
if (hasExcessiveLinks) reasons.push('Link spam');

const severity = reasons.length >= 3 ? 'HIGH' : reasons.length >= 2 ? 'MEDIUM' : 'LOW';

return [{
  json: {
    ...message,
    is_violation: isViolation,
    violation_reasons: reasons,
    severity: severity,
    checked_at: new Date().toISOString()
  }
}];
